import re
import logging
from taf.ul.mobile.ui.android.mobile import Mobile
from taf.ul.mobile.ui.android.exceptions import SelectFailure, GetInetUeIpFailed
from taf.ul.mobile.ui.android.utils import (get_nodes_by_filter, get_checked_node_text,
                                            get_selected_checkedtextview_node)


class Harmony(Mobile):

    def enable_airplane(self):
        if self._is_airplane_switch_enabled():
            logging.info("airplane mode is enabled")
            return

        self._tap_airplane_switch()

    def disable_airplane(self):
        if not self._is_airplane_switch_enabled():
            logging.info("airplane mode is disabled")
            return

        self._tap_airplane_switch()

    def _is_airplane_switch_enabled(self):
        self._open_setting()
        self._open_menu_by_searching_in_settings("Mobile network")

        nodes = self._get_widgetswitch_nodes()
        checked_node = get_selected_checkedtextview_node(nodes)
        return checked_node is not None

    def _tap_airplane_switch(self):
        nodes = self._get_widgetswitch_nodes()
        self._tap_widgetswitch_node(nodes[0])

    def switch_network_mode(self, mode_name, *args):
        self._open_setting()
        self._open_menu_by_searching_in_settings("5G network mode")
        self._tap_5g_network_mode()

        if self._get_selected_network_mode() == mode_name:
            logging.info("has selected specified mode, no action")
        else:
            self._select_5g_network_mode(mode_name)
            selected_node_title = self._get_selected_network_mode()
            if selected_node_title != mode_name:
                raise SelectFailure(selected_node_title)
        self._close_setting()

    def switch_apn(self, apn_name):
        self._open_setting()
        self._open_menu_by_searching_in_settings("Access Point Names (APNs)")
        self._tap_access_point_names()

        if self._get_selected_node_title() == apn_name:
            logging.info("has selected specified apn, no action")
        else:
            self._select_apn(apn_name)
            selected_node_title = self._get_selected_node_title()
            if selected_node_title != apn_name:
                raise SelectFailure(selected_node_title)
        self._close_setting()

    def _tap_5g_network_mode(self):
        self._click_menu("5G network mode")

    def _select_5g_network_mode(self, mode_name):
        self._click_menu(mode_name)

    def _tap_access_point_names(self):
        self._click_menu("Access Point Names (APNs)")

    def _select_apn(self, apn_name):
        self._click_menu(apn_name)

    def get_network_mode(self):
        self._open_setting()
        self._open_menu_by_searching_in_settings("5G network mode")
        self._tap_5g_network_mode()
        network_mode = self._get_selected_network_mode()
        self._close_setting()

        return network_mode

    def get_access_point_name(self):
        self._open_setting()
        self._open_menu_by_searching_in_settings("Access Point Names (APNs)")
        self._tap_access_point_names()
        apn = self._get_selected_node_title()
        self._close_setting()

        return apn

    def _get_selected_network_mode(self):
        ui_xml_content = self._adb_proxy.get_ui_xml_content()
        nodes = get_nodes_by_filter(ui_xml_content, '//node[@class="android.widget.CheckedTextView"]')
        return get_checked_node_text(nodes)

    def get_ue_ip(self):
        """
        lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN group default qlen 1000
            inet 127.0.0.1/8 scope host lo
               valid_lft forever preferred_lft forever
        8: rmnet0: <NOARP,UP,LOWER_UP> mtu 1400 qdisc pfifo_fast state UNKNOWN group default qlen 1000
            inet 172.250.184.148/32 scope global rmnet0
               valid_lft forever preferred_lft forever
        20: rmnet_ims00: <NOARP,UP,LOWER_UP> mtu 1280 qdisc pfifo_fast state UNKNOWN group default qlen 1000
            inet 10.64.2.185/32 scope global rmnet_ims00
               valid_lft forever preferred_lft forever
        """
        output = self._adb_proxy.get_ip_config_report()
        result = re.search(r"inet (\d+.\d+.\d+.\d+).+rmnet0", output)
        if not result:
            raise GetInetUeIpFailed(output)
        return result.group(1)
